    logic [dma_pkg::HADDR_W-1:0] a_lo;
    /* verilator lint_on UNUSEDSIGNAL */
    logic [dma_pkg::LEN_W-1:0]   bytes_to_b;
    a_lo       = a - ((a >> 10) << 10);          // a mod 1024
    bytes_to_b = 32'd1024 - dma_pkg::LEN_W'(a_lo);        // 1 .. 1024
    beats_to_boundary = bytes_to_b >> LBE;
