  function automatic [dma_pkg::LEN_W-1:0] min3(input logic [dma_pkg::LEN_W-1:0] x,
                                      input logic [dma_pkg::LEN_W-1:0] y,
                                      input logic [dma_pkg::LEN_W-1:0] z);
    logic [dma_pkg::LEN_W-1:0] m;
    m = (x < y) ? x : y;
    m = (m < z) ? m : z;
    min3 = m;
  endfunction

  // read burst candidate: min(MAX, rem, boundary, fifo-space)
  logic [dma_pkg::LEN_W-1:0] r_space, r_cand;
  logic             r_can_issue;
  always_comb begin
    r_space     = dma_pkg::LEN_W'(DEPTH) - dma_pkg::LEN_W'(fifo_level);
    r_cand      = min3(dma_pkg::LEN_W'(dma_pkg::MAX_BURST_BEATS), r_rem, beats_to_boundary(r_addr));
    if (r_space < r_cand) r_cand = r_space;
    r_can_issue = (rstate == R_IDLE) && (r_rem != 0) && (r_cand != 0);
  end

  // write burst candidate: min(MAX, rem, boundary), gated by available beats
  logic [dma_pkg::LEN_W-1:0] w_avail, w_bmax, w_cand;
  logic             read_complete, w_can_issue;
  always_comb begin
    w_avail       = dma_pkg::LEN_W'(fifo_level);
    w_bmax        = min3(dma_pkg::LEN_W'(dma_pkg::MAX_BURST_BEATS), w_rem, beats_to_boundary(w_addr));
    read_complete = (r_rem == 0) && (rstate == R_IDLE);
    w_cand        = (w_avail < w_bmax) ? w_avail : w_bmax;
    w_can_issue   = (wstate == W_IDLE) && (w_rem != 0) && (w_cand != 0) &&
                    ((w_avail >= w_bmax) || read_complete);
  end

